/** কারনেল_মান 안의 연결형 বাইট_মান প্রবাহ_মান. Ethernet/TCP 패킷 스택이 아닌 루프백 socket স্তর_মান. */
public final class প্রবাহ_নেটওয়ার্ক {
    static int[] অবস্হা_মান = new int[16], পোর্ট_মান = new int[16], 짝 = new int[16], পিয়ার_পোর্ট = new int[16], অপেক্ষা_মান = new int[16], 묶임 = new int[16];
    static int[] সম্মুখ_মান = new int[16], 수 = new int[16], ডাটা = new int[16 * 1024];
    static int পরবর্তী_দফা = 50000;
    static int যাচাই_করা(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && অবস্হা_মান[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int পোর্ট_নম্বর) { for (int লুপ_সূচি = 0; লুপ_সূচি < 16; লুপ_সূচি++) if (অবস্হা_মান[লুপ_সূচি] != 0 && 묶임[লুপ_সূচি] != 0 && পোর্ট_মান[লুপ_সূচি] == পোর্ট_নম্বর) return true; return false; }
    public static int ক্রিয়েট_ভুক্তি() {
        for (int লুপ_সূচি = 0; লুপ_সূচি < 16; লুপ_সূচি++) if (অবস্হা_মান[লুপ_সূচি] == 0) { অবস্হা_মান[লুপ_সূচি] = 1; পিয়ার_পোর্ট[লুপ_সূচি] = পোর্ট_মান[লুপ_সূচি] = সম্মুখ_মান[লুপ_সূচি] = 수[লুপ_সূচি] = অপেক্ষা_মান[লুপ_সূচি] = 묶임[লুপ_সূচি] = 0; 짝[লুপ_সূচি] = -1; return লুপ_সূচি + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int পোর্ট_নম্বর) {
        int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (অবস্হা_মান[লুপ_সূচি] != 1 || পোর্ট_নম্বর < 0 || পোর্ট_নম্বর > 65535) return -22;
        if (পোর্ট_নম্বর == 0) { do { পোর্ট_নম্বর = পরবর্তী_দফা++; if (পরবর্তী_দফা > 65535) পরবর্তী_দফা = 50000; } while (사용중(পোর্ট_নম্বর)); }
        if (사용중(পোর্ট_নম্বর)) return -98; পোর্ট_মান[লুপ_সূচি] = পোর্ট_নম্বর; 묶임[লুপ_সূচি] = 1; অবস্হা_মান[লুপ_সূচি] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9; if (অবস্হা_মান[লুপ_সূচি] != 2 || 연결대기한도 < 1) return -22; অবস্হা_মান[লুপ_সূচি] = 3; return 0; }
    public static int সংযোগ_স্থাপনা(int 열린파일번호, int 통신주소, int পোর্ট_নম্বর) {
        int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (পোর্ট_নম্বর < 1 || পোর্ট_নম্বর > 65535 || অবস্হা_মান[লুপ_সূচি] > 2) return -22;
        int 수신쪽 = -1; for (int অন্তর_জোড়_পদ = 0; অন্তর_জোড়_পদ < 16; অন্তর_জোড়_পদ++) if (অবস্হা_মান[অন্তর_জোড়_পদ] == 3 && পোর্ট_মান[অন্তর_জোড়_পদ] == পোর্ট_নম্বর) 수신쪽 = অন্তর_জোড়_পদ;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int অন্তর_জোড়_পদ = 0; অন্তর_জোড়_পদ < 16; অন্তর_জোড়_পদ++) if (অপেক্ষা_মান[অন্তর_জোড়_পদ] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (অবস্হা_মান[লুপ_সূচি] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = ক্রিয়েট_ভুক্তি(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        অবস্হা_মান[লুপ_সূচি] = অবস্হা_মান[다른번호] = 4; 짝[লুপ_সূচি] = 다른번호; 짝[다른번호] = লুপ_সূচি; পোর্ট_মান[다른번호] = পোর্ট_নম্বর; পিয়ার_পোর্ট[লুপ_সূচি] = পোর্ট_নম্বর; পিয়ার_পোর্ট[다른번호] = পোর্ট_মান[লুপ_সূচি]; অপেক্ষা_মান[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int স্বীকার_করুন_সংযোগ(int 열린파일번호) { int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9; if (অবস্হা_মান[লুপ_সূচি] != 3) return -22; for (int অন্তর_জোড়_পদ = 0; অন্তর_জোড়_পদ < 16; অন্তর_জোড়_পদ++) if (অবস্হা_মান[অন্তর_জোড়_পদ] != 0 && অপেক্ষা_মান[অন্তর_জোড়_পদ] == লুপ_সূচি + 1) { অপেক্ষা_মান[অন্তর_জোড়_পদ] = 0; return অন্তর_জোড়_পদ + 40; } return -11; }
    public static int লেখা(int 열린파일번호, int 항목수) {
        int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9; if (অবস্হা_মান[লুপ_সূচি] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int অন্তর_জোড়_পদ = 짝[লুপ_সূচি]; if (অন্তর_জোড়_পদ < 0) return -32; int 총수 = 1024 - 수[অন্তর_জোড়_পদ]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int তুলনা_পদ = 0; তুলনা_পদ < 총수; তুলনা_পদ++) ডাটা[অন্তর_জোড়_পদ * 1024 + (সম্মুখ_মান[অন্তর_জোড়_পদ] + 수[অন্তর_জোড়_পদ] + তুলনা_পদ) % 1024] = 되돌림망.ফরোয়ার্ড_মান[তুলনা_পদ]; 수[অন্তর_জোড়_পদ] += 총수; return 총수;
    }
    public static int পড়া(int 열린파일번호, int 항목수) {
        int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9; if (অবস্হা_মান[লুপ_সূচি] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[লুপ_সূচি] == 0) return 짝[লুপ_সূচি] < 0 ? 0 : -11; if (항목수 > 수[লুপ_সূচি]) 항목수 = 수[লুপ_সূচি];
        for (int তুলনা_পদ = 0; তুলনা_পদ < 항목수; তুলনা_পদ++) 되돌림망.ফরোয়ার্ড_মান[তুলনা_পদ] = ডাটা[লুপ_সূচি * 1024 + (সম্মুখ_মান[লুপ_সূচি] + তুলনা_পদ) % 1024]; সম্মুখ_মান[লুপ_সূচি] = (সম্মুখ_মান[লুপ_সূচি] + 항목수) % 1024; 수[লুপ_সূচি] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int লুপ_সূচি = যাচাই_করা(열린파일번호); return লুপ_সূচি < 0 ? -9 : পোর্ট_মান[লুপ_সূচি]; }
    public static int 상대창구읽기(int 열린파일번호) { int লুপ_সূচি = যাচাই_করা(열린파일번호); return লুপ_সূচি < 0 ? -9 : পিয়ার_পোর্ট[লুপ_সূচি]; }
    public static int বন্ধ_করুন(int 열린파일번호) {
        int লুপ_সূচি = যাচাই_করা(열린파일번호); if (লুপ_সূচি < 0) return -9;
        if (অবস্হা_মান[লুপ_সূচি] == 3) for (int অন্তর_জোড়_পদ = 0; অন্তর_জোড়_পদ < 16; অন্তর_জোড়_পদ++) if (অপেক্ষা_মান[অন্তর_জোড়_পদ] == লুপ_সূচি + 1) { if (짝[অন্তর_জোড়_পদ] >= 0) 짝[짝[অন্তর_জোড়_পদ]] = -1; অবস্হা_মান[অন্তর_জোড়_পদ] = অপেক্ষা_মান[অন্তর_জোড়_পদ] = 묶임[অন্তর_জোড়_পদ] = 0; }
        if (짝[লুপ_সূচি] >= 0) 짝[짝[লুপ_সূচি]] = -1; অবস্হা_মান[লুপ_সূচি] = 묶임[লুপ_সূচি] = 수[লুপ_সূচি] = অপেক্ষা_মান[লুপ_সূচি] = 0; return 0;
    }
}
